  /// 原值。基线把首个中点换成空格再展示，那是排版，留给 Dart。
  final String? recommendReason;

  const SearchTrendingItem({
    required this.keyword,
    required this.showName,
    this.icon,
    this.showLiveIcon,
    this.recommendReason,
  });

  @override
  int get hashCode =>
      keyword.hashCode ^
      showName.hashCode ^
      icon.hashCode ^
      showLiveIcon.hashCode ^
      recommendReason.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is SearchTrendingItem &&
          runtimeType == other.runtimeType &&
          keyword == other.keyword &&
          showName == other.showName &&
          icon == other.icon &&
          showLiveIcon == other.showLiveIcon &&
          recommendReason == other.recommendReason;
}

/// 热搜榜/默认词的结果。
