/// 视频条目。
class SearchVideoItem {
  final PlatformInt64? id;
  final PlatformInt64? aid;
  final String? bvid;
  final String? arcurl;
  final List<TitleSpan> titleSpans;

  /// `title_spans` 拼接出的纯文本。
  final String title;
  final String? description;
  final String? pic;
  final PlatformInt64? pubdate;
  final PlatformInt64? senddate;

  /// **秒**。接口给的是 `"12:34"`，读不出来时为 0。
  final PlatformInt64 durationSecs;
  final SearchOwner owner;
  final SearchStat stat;

  /// `video` / `ketang` / `live_room` …。刻意不是枚举：服务端随时会加
  /// 新值，收成枚举会让新值变成解析错误。
  final String? itemType;
  final PlatformInt64? roomid;
  final PlatformInt64? isUnionVideo;
  final String? tag;

  const SearchVideoItem({
    this.id,
    this.aid,
    this.bvid,
    this.arcurl,
    required this.titleSpans,
    required this.title,
    this.description,
    this.pic,
    this.pubdate,
    this.senddate,
    required this.durationSecs,
    required this.owner,
    required this.stat,
    this.itemType,
    this.roomid,
    this.isUnionVideo,
    this.tag,
  });

  @override
  int get hashCode =>
      id.hashCode ^
      aid.hashCode ^
      bvid.hashCode ^
      arcurl.hashCode ^
      titleSpans.hashCode ^
      title.hashCode ^
      description.hashCode ^
      pic.hashCode ^
      pubdate.hashCode ^
      senddate.hashCode ^
      durationSecs.hashCode ^
      owner.hashCode ^
      stat.hashCode ^
      itemType.hashCode ^
      roomid.hashCode ^
      isUnionVideo.hashCode ^
      tag.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is SearchVideoItem &&
          runtimeType == other.runtimeType &&
          id == other.id &&
          aid == other.aid &&
          bvid == other.bvid &&
          arcurl == other.arcurl &&
          titleSpans == other.titleSpans &&
          title == other.title &&
          description == other.description &&
          pic == other.pic &&
          pubdate == other.pubdate &&
          senddate == other.senddate &&
          durationSecs == other.durationSecs &&
          owner == other.owner &&
          stat == other.stat &&
          itemType == other.itemType &&
          roomid == other.roomid &&
          isUnionVideo == other.isUnionVideo &&
          tag == other.tag;
}

